import cn from 'classnames';
import { ButtonProps } from './button.types';
import './button.scss';

// Plain function component -- was React.forwardRef (the only forwardRef use
// in aem-core-lib/src/lib/*/*.tsx). Stripped for the EDS POC's DOM build:
// dom-runtime.js's build() only handles `typeof type === 'function'`
// (libs/dom-runtime/dom-runtime.js) and a forwardRef component's type is
// `typeof === 'object'` ({$$typeof, render}), so DomComp(fixture) threw
// "DomComp is not a function". Confirmed no caller across
// aem-core-lib/ac-core-lib passes a `ref` to <Button> (only button.tsx
// itself forwarded it, to the inner <button>/<a>) -- see build report.
export const Button = (
  {
    id,
    text,
    buttonLink,
    target = '_parent',
    className,
    typeTransform,
    type,
    icon,
    colorType,
    disabled,
    dataLayer,
    AEMclassNameSlot1,
    AEMclassNameSlot2,
    AEMclassNameSlot3,
    useRootClassName = true,
    ...props
  }: ButtonProps,
) => {
  const typeTextTransform = cn({
    'text-lowercase': typeTransform === 'lowercase',
    'text-uppercase': typeTransform === 'uppercase',
    'text-capitalize': typeTransform === 'capitalize',
  });
  const extraClasses = cn({
    AEMclassNameSlot1,
    AEMclassNameSlot2,
    AEMclassNameSlot3,
  });
  const buttonType = cn({
    'cmp-button--primary': type === 'primary',
    'cmp-button--secondary': type === 'secondary',
    'cmp-button--tetriary': type === 'tetriary',
  });

  const buttonColorType = cn({
    'cmp-button--color-primary': colorType === 'primary',
    'cmp-button--color-secondary': colorType === 'secondary',
  });

  const getButtonStructure = () => (
    <button
      {...props}
      id={id}
      type="button"
      className={cn('cmp-button')}
      data-cmp-clickable=""
      data-cmp-data-layer=""
      disabled={disabled}
    >
      {icon && <span className={cn(`cmp-button__icon cmp-button__icon--${icon}`)} aria-hidden="true"></span>}
      <span className="cmp-button__text">{text}</span>
    </button>
  );

  const getLinkStructure = () => (
    <a
      {...props}
      id={id}
      href={buttonLink?.url}
      target={target}
      className="cmp-button"
      data-cmp-clickable=""
      data-cmp-data-layer=""
    >
      {icon && <span className={cn(`cmp-button__icon cmp-button__icon--${icon}`)} aria-hidden="true"></span>}
      <span className="cmp-button__text">{text}</span>
    </a>
  );

  return (
    <div
      className={cn(
        useRootClassName ? 'button' : '',
        className,
        typeTextTransform,
        buttonType,
        buttonColorType,
        extraClasses,
      )}
    >
      {buttonLink && buttonLink.url ? getLinkStructure() : getButtonStructure()}
    </div>
  );
};

export default Button;
